L("التقليد", [36, 38],
  ["يعرف التقليد لغة واصطلاحا", "يبين أحكام التقليد: الواجب والجائز والمحرم", "يميز التقليد من الاتباع"],
  "قال تعالى: ﴿فاسألوا أهل الذكر إن كنتم لا تعلمون﴾، وذم الله الذين قالوا: ﴿إنا وجدنا آباءنا على أمة﴾. فمتى يكون التقليد واجبا، ومتى يكون مذموما؟",
  "التقليد لغة: جعل القلادة في العنق، واصطلاحا: قبول قول من ليس قوله حجة دون معرفة دليله. ولا يسمى الأخذ بقول النبي ﷺ والإجماع ورجوع القاضي إلى الشهود تقليدا بل اتباعا. والتقليد واجب على غير المجتهد في الفروع، لقوله تعالى: ﴿فاسألوا أهل الذكر﴾ وإجماع الصحابة. ويمنع عند الجمهور في أصول الدين لوجوب الجزم فيها. والمذموم: الإعراض عن النصوص تقليدا للآباء، أو ترك المجتهد ما أداه إليه اجتهاده.",
  ["التقليد لغة: جعل القلادة في العنق.", "اصطلاحا: قبول قول من ليس قوله حجة دون معرفة دليله.", "الأخذ بقول النبي ﷺ والإجماع اتباع لا تقليد.", "واجب على العامي في الفروع: ﴿فاسألوا أهل الذكر﴾.", "ممنوع في أصول الدين عند الجمهور.", "قد يكون واجبا أو جائزا أو حراما (د. محمد المختار الشنقيطي)."],
  ("هل يجوز للعامي أن يعمل بالأحاديث مباشرة من الكتب؟", "قال الإمام أحمد: «لا يعمل حتى يسأل أهل العلم»؛ لأنه لا يميز الصحيح من غيره ولا الناسخ من المنسوخ."),
  [S("التعريف", ["لغة: جعل القلادة في العنق؛ كأن المسؤول جعل الفتوى في عنق السائل.", "اصطلاحا: قبول قول من ليس قوله حجة دون معرفة دليله.", "ليس تقليدا بل اتباعا: الأخذ بقول النبي ﷺ، وبالإجماع، ورجوع القاضي إلى الشهود."]),
   S("أحكام التقليد", table=[["الحكم", "مجاله", "الدليل"], ["واجب", "على غير المجتهد في الفروع، وعند نزول النازلة", "﴿فاسألوا أهل الذكر﴾، إجماع الصحابة، استحالة تكليف الكل بالاجتهاد"], ["جائز", "للتعلم أو لمن لم تنزل به نازلة بعد", "—"], ["ممنوع", "في أصول الدين عند الجمهور، وفي الإعراض عن النصوص تعصبا", "﴿إنا وجدنا آباءنا على أمة﴾"]]),
   S("التقليد المذموم", ["الإعراض عن نصوص الشرع اكتفاء بتقليد الآباء.", "أن يترك المجتهد ما أداه إليه اجتهاده تقليدا لغيره.", "التمسك بقول مع قيام الحجة على خلافه، تعصبا للمذهب أو للبدعة."])],
  apps=[("ما الفرق بين التقليد والاتباع؟", "الاتباع أخذ بالحجة كقول النبي ﷺ والإجماع، والتقليد أخذ بقول من ليس قوله حجة دون معرفة دليله."), ("لماذا منع الجمهور التقليد في العقائد؟", "لأنها يطلب فيها الجزم والقطع، ولا يحصل ذلك بالتقليد.")]),
