L("التجديد في العالم الإسلامي: مفهومه والظروف التي دعت إليه", [41, 42],
  ["يعرف التجديد لغة وشرعا", "يذكر نماذج من المجددين عبر التاريخ", "يبين الظروف التي دعت إلى الإصلاح"],
  "قال النبي ﷺ: «إن الله يبعث إلى هذه الأمة على رأس كل مائة سنة من يجدد لها دينها». فما معنى التجديد؟ وهل هو تغيير للدين؟",
  "التجديد لغة: جعل القديم جديدا وإعادته إلى حالته الأولى، ويتضمن: وجود الشيء أولا، ثم طروء ما أبلاه، ثم إعادته. وشرعا: إعادة الدين مفهوما وممارسة إلى صورته الأولى قبل التحريف، لا تغيير طبيعته. وتنوعت أدوار المجددين: الحسن البصري في الشعور الديني، وعمر بن عبد العزيز في السياسة الشرعية، والشافعي في منهج الاستدلال، وابن تيمية في التصور السلفي. ودعا إليه الجمود الفقهي وانحراف بعض الخطاب الصوفي.",
  ["التجديد لغة: إعادة الشيء إلى أول أمره.", "معانيه الثلاثة: وجود الشيء أولا، ثم بلاه، ثم إعادته.", "«إن الله يبعث إلى هذه الأمة على رأس كل مائة سنة من يجدد لها دينها» (أبو داود).", "القرضاوي: التجديد العودة بالشيء إلى ما كان عليه يوم نشأ، لا تغيير طبيعته.", "مالك: «لن يصلح آخر هذه الأمة إلا بما صلح به أولها».", "نماذج: الحسن البصري، عمر بن عبد العزيز، الشافعي، ابن تيمية."],
  ("هل يعني التجديد استبدال أحكام الدين بأحكام حديثة؟", "لا؛ التجديد تقوية ما وهى وترميم ما بلي حتى يعود الدين إلى صورته الأولى، أما تغيير طبيعته فليس من التجديد في شيء."),
  [S("مفهوم التجديد", ["لغة: صيره جديدا، أي أعاده إلى حالته الأولى.", "شرعا: إعادة الدين مفهوما وممارسة إلى صورته الأولى قبل التحريف بالزيادة أو النقص.", "المودودي: «المجدد كل من أحيا معالم الدين بعد طمسها»."]),
   S("نماذج من المجددين", table=[["المجدد", "ميدان تجديده"], ["الحسن البصري", "الشعور الديني لدى العامة"], ["عمر بن عبد العزيز", "السياسة الشرعية في الحكم"], ["الشافعي", "المنهج العلمي في الاجتهاد والاستدلال"], ["ابن تيمية", "التصور السلفي ونقد الفلسفات المنحرفة"]]),
   S("الظروف الداعية إليه", ["جمود الخطاب الفقهي: حل الشرح محل المتن، والفرع محل الأصل، وأقفل باب الاجتهاد.", "انحراف بعض الخطاب الصوفي: الانعزال عن الدنيا، ومزجه بالفلسفة الإشراقية، وطرائق الذكر والسماع.", "والتجديد يشمل كل مناحي الحياة: العقيدة والأخلاق والسياسة والاقتصاد والمجتمع."])],
  apps=[("ما المعاني الثلاثة التي يتضمنها التجديد لغة؟", "أن الشيء كان موجودا، ثم طرأ عليه ما أبلاه، ثم أعيد إلى حالته الأولى."), ("اذكر مقولة مالك في الإصلاح.", "«لن يصلح آخر هذه الأمة إلا بما صلح به أولها».")]),
L("ابن تيمية", [43, 46],
  ["يعرف بابن تيمية ونشأته", "يبين العوامل التي أثرت في فكره", "يعرض منهجه وأهم القضايا التي عالجها"],
  "عاش ابن تيمية في عصر سقوط بغداد وغزو التتار والحروب الصليبية. فكيف أثر ذلك في فكره ومنهجه الإصلاحي؟",
  "أبو العباس أحمد تقي الدين بن تيمية، ولد بحران سنة 661 هـ، وانتقلت أسرته إلى دمشق فرارا من المغول، وتولى التدريس مكان أبيه وهو ابن اثنتين وعشرين سنة. تأثر فكره بغزو التتار والحروب الصليبية والفتن الداخلية، واختلاط المجتمع وظهور البدع، وركود العلم وسيطرة التقليد. ومنهجه: الرجوع إلى الكتاب والسنة وآثار الصحابة، وعدم التعصب. وعالج قضايا: كرامات الأولياء، والتوسل بالموتى، وزيارة القبور، والإمامة. وتوفي سنة 728 هـ.",
  ["ولد بحران سنة 661 هـ، ونشأ بدمشق في أسرة علم حنبلية.", "العوامل السياسية: غزو التتار وسقوط بغداد (656 هـ)، الحروب الصليبية، الفتن الداخلية.", "العوامل الاجتماعية: اختلاط الأجناس وظهور البدع.", "العوامل العلمية: ركود الأذهان وسيطرة التقليد.", "منهجه: الكتاب والسنة وآثار الصحابة، وعدم التعصب.", "توفي سنة 728 هـ."],
  ("بم امتاز فكر ابن تيمية في التجديد؟", "بالعودة إلى الأصول: الكتاب والسنة وفهم الصحابة، ونبذ التعصب المذهبي، ومناقشة المتكلمين والفلاسفة بأدلتهم."),
  [S("نشأته", ["أبو العباس أحمد تقي الدين بن شهاب الدين بن تيمية، ولد بحران سنة 661 هـ.", "انتقلت أسرته إلى دمشق بسبب غارات المغول، وكان أبوه شيخ دار الحديث.", "تولى التدريس بعد وفاة أبيه وهو ابن اثنتين وعشرين سنة."]),
   S("العوامل المؤثرة في فكره", table=[["الناحية", "مظاهرها"], ["السياسية", "غزو التتار وسقوط بغداد 656 هـ، الحروب الصليبية، الفتن بين المماليك والتتار"], ["الاجتماعية", "اختلاط الأجناس والفارين من الحروب، وظهور عوائد وبدع"], ["العلمية", "قلة الإنتاج، ركود الأذهان، إقفال باب الاجتهاد وسيطرة التقليد"]]),
   S("منهجه وقضايا عالجها", ["الشريعة أصلها القرآن، فسره النبي ﷺ ونقله الصحابة؛ فلا يتبع بعد الله ورسوله إلا الصحابة.", "عدم التعصب: كان حنبليا ثم درس المذاهب كلها وخالفها في بعض آرائه.", "كرامات الأولياء: يثبتها.", "التقرب بالموتى والاستغاثة بهم: يمنعه، والتقرب إنما يكون بالاقتداء بهم.", "زيارة القبور للاتعاظ: جائزة بل مندوبة."]),
   S("(تصحيح: …)", ["ص45: «أما زيارة قبر بعينه فلا تجوز ولو كان قبر نبي». (تصحيح: الذي منعه ابن تيمية هو شد الرحال لمجرد زيارة القبور، أما الزيارة الشرعية للسلام والدعاء والاعتبار فيجيزها ولو كان قبر نبي.)"])],
  apps=[("متى سقطت بغداد في يد التتار؟", "سنة 656 هـ، وبها سقطت الخلافة العباسية."), ("ما موقف ابن تيمية من كرامات الأولياء؟", "يثبتها لمن كان صادقا ملتزما بالتقوى والإخلاص.")]),
L("جمال الدين الأفغاني وتلميذه محمد عبده", [47, 48],
  ["يعرف بجمال الدين الأفغاني ومحمد عبده", "يبين أثرهما في النهضة الإسلامية", "يذكر أهم مؤلفات محمد عبده"],
  "أسس جمال الدين الأفغاني مع تلميذه محمد عبده في باريس جمعية «العروة الوثقى». فما دورهما في الإصلاح؟",
  "جمال الدين الأفغاني (1838–1897م) تلقى العلوم الدينية والعقلية، ثم رحل إلى الهند ومصر والآستانة وأوروبا، ونشر في مصر تعاليمه في الحرية والشورى ومقاومة الاستعمار، فكان أثره بالغا في النهضة الوطنية، ونفي إلى الهند، ثم أنشأ مع محمد عبده جمعية العروة الوثقى بباريس، وتوفي بالآستانة 1897م. ومحمد عبده (1849–1905م) تعلم في الأزهر، واشترك في الثورة العرابية فنفي، ثم عاد وشغل مناصب قضائية حتى صار مفتي الديار المصرية، وسعى إلى تحرير العقل من الجمود وإحياء الاجتهاد.",
  ["الأفغاني: ولد 1838م، وتلقى العربية والعلوم الدينية والفلسفة والرياضيات.", "دخل مصر 1871م وبث تعاليمه، فكان من عوامل النهضة الوطنية.", "نفاه الخديوي توفيق إلى الهند بعد الثورة العرابية.", "أنشأ مع محمد عبده جمعية العروة الوثقى في باريس.", "محمد عبده: الأزهر، دار العلوم، الثورة العرابية، النفي إلى بيروت، ثم المفتي العام.", "مؤلفاته: رسالة التوحيد، الإسلام والنصرانية بين العلم والمدنية، شرح نهج البلاغة."],
  ("ما أبرز إسهام محمد عبده في الإصلاح؟", "تحرير العقل من الجمود، وإحياء الاجتهاد الفقهي لمواكبة تطورات العصر، وإيقاظ وعي الأمة نحو التحرر."),
  [S("جمال الدين الأفغاني (1838–1897م)", ["تلقى العربية والأفغانية وعلوم الدين والتاريخ والمنطق والفلسفة والرياضيات، ثم درس العلوم الحديثة في الهند.", "دخل مصر وأقام بها، فخطا فن الكتابة والخطابة خطوات واسعة بفضله.", "دعا إلى الشورى والحرية، فأخرجه الخديوي توفيق إلى الهند.", "أسس مع محمد عبده جمعية العروة الوثقى في باريس.", "مات بالآستانة في 9 مارس 1897م."]),
   S("محمد عبده (1849–1905م)", ["ولد بالبحيرة، وتعلم بالأزهر، ودرس التاريخ بدار العلوم سنة 1879م.", "اشترك في الثورة العرابية فسجن ونفي إلى بيروت، ثم لحق بأستاذه في باريس.", "عاد بعفو الخديوي، وشغل مناصب قضائية حتى صار المفتي العام، وأسس جمعية إحياء العلوم العربية.", "توفي بالإسكندرية في 11 يوليو 1905م.", "مؤلفاته: رسالة التوحيد، الرد على هانوتو، الإسلام والنصرانية بين العلم والمدنية، شرح نهج البلاغة، تحقيق دلائل الإعجاز."]),
   S("(تصحيح: …)", ["ص48: «وفي 25 يونيو 1890م عين عضوا في مجلس شورى القوانين». (تصحيح: كان ذلك سنة 1899م، وهي السنة نفسها التي عين فيها مفتيا للديار المصرية.)"])],
  apps=[("ما الجمعية التي أسسها الأفغاني ومحمد عبده في باريس؟", "جمعية العروة الوثقى، وأصدرت مجلة بالاسم نفسه."), ("لماذا نفي محمد عبده؟", "لاشتراكه في الثورة العرابية.")]),
L("عبد الحميد بن باديس", [49, 51],
  ["يعرف بابن باديس ونشأته", "يبين الظروف التي واجهها في الجزائر", "يبرز مزايا شخصيته ودوره في مقاومة الاستعمار"],
  "احتفلت فرنسا سنة 1930م بمرور قرن على احتلال الجزائر وقالت إنها باقية إلى الأبد، فرد ابن باديس: «شعب الجزائر مسلم وإلى العروبة ينتسب». فمن هو؟",
  "عبد الحميد بن باديس، ولد سنة 1889م بقسنطينة في أسرة علم، وتعلم على حمدان الونيسي ثم في جامع الزيتونة على علماء منهم محمد الطاهر بن عاشور. لقي البشير الإبراهيمي في المدينة فوضعا أسس جمعية العلماء المسلمين الجزائريين. قاوم سياسة الإدماج والفرنسة والتجنيس، وكان مربيا ومفسرا ومحدثا وأديبا وخطيبا. توفي في أبريل 1940م، والجيل الذي رباه قام بالثورة الجزائرية سنة 1954م.",
  ["ولد سنة 1889م بقسنطينة.", "تعلم على حمدان الونيسي ست سنوات، ثم في الزيتونة أربع سنوات.", "لقي البشير الإبراهيمي في المدينة، فأسسا جمعية العلماء المسلمين.", "قاوم الإدماج والفرنسة والتجنيس، ودافع عن الشخصية العربية المسلمة.", "كان مربيا ومفسرا ومحدثا وأديبا (مجلة الشهاب) وخطيبا.", "توفي في أبريل 1940م، وجيله قام بثورة 1954م."],
  ("كيف واجه ابن باديس سياسة فرنسا في الجزائر؟", "بالتربية والتعليم العربي الإسلامي، وتأسيس جمعية العلماء المسلمين، والكتابة في «الشهاب»، والدفاع عن هوية الجزائر العربية المسلمة."),
  [S("مولده ونشأته", ["ولد سنة 1889م في قسنطينة من أسرة عريقة في العلم، وحفظ القرآن مبكرا.", "درس على الشيخ حمدان الونيسي ست سنوات، ثم بجامع الزيتونة أربع سنوات على محمد الطاهر بن عاشور ومحمد النخلي القيرواني وغيرهما.", "حج ومكث بالمدينة ثلاثة أشهر، ولقي البشير الإبراهيمي، ثم زار سوريا ومصر ولبنان."]),
   S("الظروف المحيطة به", ["الاحتلال الفرنسي الذي احتفل سنة 1930م بمرور قرن على الاحتلال.", "طمس الشخصية الجزائرية: تحريف القيم، محاربة العربية والتعليم العربي.", "مقاومة ابن باديس بالقلب واللسان والقلم عبر جمعية العلماء المسلمين."]),
   S("مزايا شخصيته", ["مرب كبير كون الجيل الجزائري على أسس النهضة الإسلامية.", "مفسر يمزج بين الطريقة السلفية وروح العصر، ومحدث عميق الفهم.", "أديب شاعر: «شعب الجزائر مسلم — وإلى العروبة ينتسب».", "خطيب مفوه."]),
   S("(تصحيح: …)", ["ص49: من شيوخه في الزيتونة «البشير جعفر». (تصحيح: هو الشيخ البشير صفر.)"])],
  apps=[("ما الجمعية التي أسسها ابن باديس؟", "جمعية العلماء المسلمين الجزائريين، مع البشير الإبراهيمي وغيره."), ("ما أثر ابن باديس بعد وفاته؟", "الجيل الذي رباه قام بالثورة الجزائرية الكبرى سنة 1954م.")]),
# ───── علماء ومصلحون موريتانيون ─────
L("الإمام ناصر الدين: إمامته ومحاولته إقامة دولة إسلامية", [55, 57],
  ["يصف حالة البلاد قبل دعوة ناصر الدين", "يعرف بالإمام ناصر الدين ودعوته", "يبين جهاده ونتائج حركته"],
  "عرفت البلاد بعد غياب دولة المرابطين باسم «البلاد السائبة». فكيف حاول الإمام ناصر الدين إقامة دولة إسلامية فيها؟",
  "كانت البلاد قبل دعوة ناصر الدين في فوضى شاملة بعد غياب دولة المرابطين، مع انحراف في العقيدة والمعاملات وبداية الأطماع الأوروبية على السواحل. فقام الفقيه المجاهد أبو بكر بن أبهم الشمشوي (القرن الحادي عشر الهجري) بدعوة إلى الكتاب والسنة ومحاربة البدع والجهاد، ومكث الناس ثلاث سنين في «سنين التوبة». وحاول إقامة سلطة دينية، ونشر الإسلام في فوتة وجلف وكيور، لكن الصراع مع المغافرة انفجر في حرب شرببه.",
  ["حالة البلاد: «البلاد السائبة» بعد غياب دولة المرابطين.", "ناصر الدين: أبو بكر بن أبهم الشمشوي، فقيه مجاهد من القرن 11 هـ.", "دعوته: الكتاب والسنة، محاربة البدع، الأمر بالمعروف، الجهاد.", "«سنين التوبة»: ثلاث سنين من الوعظ والإرشاد.", "قاوم تجارة الرقيق الأوروبية، ونشر الإسلام في السنغال.", "حرب شرببه: صراع الزوايا والمغافرة."],
  ("لماذا تعد حركة ناصر الدين إحياء لدعوة المرابطين؟", "لأنها قامت مثلها على الكتاب والسنة، والأمر بالمعروف والنهي عن المنكر، والجهاد، ورفع الظلم عن المستضعفين."),
  [S("حالة البلاد قبل دعوته", ["فوضى شاملة بعد غياب دولة المرابطين: «البلاد السائبة» أو «بلاد السيبة».", "تدهور ديني: وصف ابن بطوطة مخالفات أهل ولاتة في الأنساب والمواريث والطهارة.", "هجرة بني حسان وما صحبها من سلب ونهب، وبداية الوجود الأوروبي على السواحل."]),
   S("حياته ودعوته", ["أبو بكر بن أبهم بن ألفغ الشمشوي، درس في المحاظر، واشتهر بالورع ونصرة السنة.", "دعا إلى التمسك بالكتاب والسنة، ونشر العقيدة الصحيحة، ومحاربة البدع والمنكرات.", "قاوم النصارى الأوروبيين ومنع التعامل معهم في تجارة البشر.", "«مكث الناس ثلاث سنين… حتى سمت العامة تلك السنين سنين التوبة» (المختار بن حامد)."]),
   S("جهاده ونتائج حركته", ["أطاح بعروش وثنية في السنغال وجعل مكانها أمراء مسلمين.", "فتحت فوتة على يد أنحوى بن أكد عبد الله، وجلف على يد الفاضل بن أبي يعدل، وكيور، وشاممة.", "اصطدمت الحركة بمصالح المغافرة والتجار الأوروبيين، فاندلعت حرب شرببه إثر منع «بب» دفع زكاته.", "شغلت الحرب الداخلية الزوايا عن فتوحاتها في الجنوب."])],
  apps=[("ما «سنين التوبة»؟", "ثلاث سنين عكف فيها الناس على مواعظ ناصر الدين فتابوا وأقبلوا على الطاعة."), ("ما سبب اندلاع حرب شرببه حسب المتداول؟", "منع «بب» دفع زكاته لسعاة ناصر الدين.")]),
L("محمذن فال بن متالي: حياته ورأيه في التعليم وبعض فتاويه", [58, 60],
  ["يعرف بالمرابط محمذن فال بن متالي", "يبين رأيه في التعلم", "يحلل بعض فتاويه"],
  "كان المرابط محمذن فال بن متالي مرجع الفتوى في زمانه، وأفتى بمساواة الرجال والنساء في طلب العلم. فمن هو؟",
  "محمذن فال بن متالي التندغي، ولد سنة 1205 هـ/1790م وتوفي سنة 1287 هـ/1870م، نشأ يتيما في رعاية أمه جليت، وطلب العلم صغيرا. كان مرجع الفتوى في زمانه، وناظر علماء عصره كمحنض باب بن اعبيد. فضل التعلم على العبادة غير الواجبة، وأفتى بمساواة الرجال والنساء في التعلم. ومن مؤلفاته: فتح الحق، وقرة عين النسوان. وله أجوبة كثيرة بطريقة السؤال والجواب.",
  ["ولد سنة 1205 هـ/1790م، وتوفي سنة 1287 هـ/1870م.", "نشأ يتيما في رعاية أمه جليت وخالته.", "أخذ عن المؤيد بن مصيوب، وأجفغ بن عفان (الطريقة الشاذلية)، وأحمد بن العاقل.", "فضل العلم على نوافل العبادة.", "أفتى بمساواة الرجال والنساء في طلب العلم.", "مؤلفاته: فتح الحق، قرة عين النسوان، أجوبة فقهية."],
  ("ما رأي ابن متالي في تعليم المرأة؟", "أفتى بمساواة الرجال والنساء في التعلم؛ لأن الشرع ساوى بينهما في الخطاب بطلب العلم."),
  [S("حياته", ["محمذن فال بن متالي بن محمذن التندغي، ولد بـ«بوك» شمال كرمسين سنة 1205 هـ/1790م، وتوفي سنة 1287 هـ/1870م.", "نشأ يتيم الأب، وأرسلته أمه لطلب العلم في الثانية عشرة.", "كان محبا للمطالعة وشراء الكتب، مضيافا يخدم ضيوفه بنفسه.", "ناظر علماء دهره: القاضي محنض باب بن اعبيد، ومحمد مولود اليعقوبي، وعبد الودود بن عبد الله."]),
   S("رأيه في التعليم", ["يفضل التعلم على العبادة غير الواجبة:", "«قد فضلوا للذكر دون مين — على التلاوة ففي وقتين — قبل طلوع الشمس بعد العصر — والعكس بالعكس لباقي الدهر — والعلم في الوقتين أو سواهما — عن غيره قد فضلوه العلما».", "ساوى بين الرجال والنساء في التعلم."]),
   S("من فتاويه", ["الجنة: فوق السماء السابعة وسقفها العرش.", "نزول القرآن: نزل من اللوح المحفوظ إلى السماء الدنيا جملة، ثم منجما في ثلاث وعشرين سنة.", "كسر اللوح عمدا: لا يكون ردة إذا قصد إغاظة صاحب اللوح لا إهانة ما فيه."]),
   S("مؤلفاته", ["فتح الحق.", "قرة عين النسوان في الفقه.", "أجوبة فقهية لمحمد مولود وعبد الودود بن عبد الله."])],
  apps=[("متى يفضل الذكر على التلاوة عند ابن متالي؟", "قبل طلوع الشمس وبعد العصر، والعكس في باقي الأوقات، والعلم مقدم عليهما في كل الأوقات."), ("ما الطريقة التي دونت بها فتاواه؟", "طريقة السؤال والجواب.")]),
L("محمد يحيى الولاتي: رحلته وفتاويه", [61, 63],
  ["يعرف بمحمد يحيى الولاتي ونشأته", "يذكر نماذج من مؤلفاته", "يبين أثر رحلته إلى الحج في مكانته العلمية"],
  "خرج محمد يحيى الولاتي إلى الحج سنة 1311 هـ، فاستغرقت رحلته سبع سنوات درس فيها وأفتى في المغرب ومصر والحجاز. فمن هو؟",
  "محمد يحيى بن محمد المختار الولاتي الداودي، الملقب بالفقيه، ولد بولاتة سنة 1259 هـ وتوفي سنة 1330 هـ. نشأ يتيما فامتهن نسخ الكتب فكانت له دراسة موسوعية. تجاوزت مؤلفاته المائة في علوم القرآن والحديث والأصول واللغة والفقه، منها: فتح الودود على مراقي السعود، ونيل السول، ومنبع الحق والتقى. وفي رحلته إلى الحج درس وأفتى في المغرب، وأكرمه السلطان عبد العزيز، ودرس الموطأ في المدينة، وأجازه علماء الإسكندرية.",
  ["ولد بولاتة سنة 1259 هـ، وتوفي سنة 1330 هـ.", "نشأ يتيما وامتهن نسخ الكتب.", "حفظ القرآن في الثامنة، ودرس خليلا على سيد أحمد بن أبي قفه.", "مؤلفاته تجاوزت المائة: فتح الودود، نيل السول، منبع الحق والتقى.", "رحلة الحج (1311 هـ) استغرقت سبع سنوات.", "درس في المدينة الموطأ وعقود الجمان والورقات، وأجازه حسن شحاته بالإسكندرية."],
  ("كيف أثر نسخ الكتب في تكوين الولاتي العلمي؟", "كان بمثابة دراسة موسوعية لما فيه من قراءة الكتاب المنسوخ وتدبره، مع ما وفره له من عيش."),
  [S("التعريف به", ["محمد يحيى بن محمد المختار بن الطالب عبد الله الداودي، عرف بلقب «الفقيه».", "ولد بولاتة سنة 1259 هـ: «بمولد الفخر الرضى يحيى انشرح — صدر العلوم والهدى عام انشرح».", "ولاتة مدينة العلم والتاريخ، ومركز تجاري ربط إفريقيا بالعالم العربي."]),
   S("من مؤلفاته", table=[["الفن", "المؤلف"], ["علوم القرآن", "نظم في الناسخ والمنسوخ ؛ التيسير والتسهيل لمعرفة أحكام التنزيل"], ["الحديث", "نظم في المصطلح ؛ اختصار الموطأ"], ["الأصول", "نيل السول على مرتقى الأصول ؛ فتح الودود على مراقي السعود ؛ توضيح المشكلات لاختصار الموافقات"], ["العربية", "شرح الفريدة ؛ مرتع الجنان على عقود الجمان"], ["الفقه", "منبع الحق والتقى ؛ شرح الرسالة"]]),
   S("رحلته وفتاويه", ["خرج إلى الحج سنة 1311 هـ، ومر بتيشيت وتندوف ومدن مغربية، وأقام بالمغرب خمسة أشهر أكرمه فيها السلطان عبد العزيز.", "درس بالمدينة المنورة الموطأ وعقود الجمان وورقات إمام الحرمين.", "أفتى في جواز حكم القاضي المالكي بالضعيف من المذهب أو بقول غير إمامه.", "دون رحلته في كتاب ضم نيفا وأربعين بين مصنف وفتوى وشرح ونظم."])],
  apps=[("كم استغرقت رحلة الولاتي إلى الحج؟", "سبع سنوات ذهابا وإيابا."), ("اذكر مؤلفا للولاتي في أصول الفقه.", "فتح الودود على مراقي السعود، أو نيل السول على مرتقى الأصول.")]),
L("المرابط محمد الأمين بن أحمد زيدان", [64, 66],
  ["يعرف بالمرابط محمد الأمين بن أحمد زيدان", "يبين طلبه للعلم وشيوخه", "يذكر مكانته ومؤلفاته"],
  "قال عنه شيخه سيدي محمد بن علي العلوشي: «والله ما استفاد مني شيئا إلا استفدت منه مثله». فمن هذا التلميذ؟",
  "محمد الأمين بن أحمد زيدان الجكني، ولد حوالي سنة 1229 هـ، وتوفي أبوه مبكرا فربته أمه فاطمة، وتعلم عليها القراءة والكتابة، وحفظ القرآن على خاله بسرعة عجيبة. رحل في طلب العلم نحو ست سنين، ومن شيوخه سيدي محمد بن علي العلوشي في الأصول. ثم عاد فكان الإمام والمفتي والقاضي والمدرس، معروفا بالكرم ونصرة المظلوم والأمر بالمعروف. وتناهز مؤلفاته الستين، منها: الرجز المفيد في غريب القرآن، والنصيحة على شرح خليل.",
  ["ولد حوالي سنة 1229 هـ من قبيلة تجكانت.", "ربته أمه فاطمة بنت سيد أحمد الحبيب، وحفظ القرآن على خاله المختار.", "طلب العلم نحو ست سنين، وأنهى رحلته عند سيدي محمد بن علي العلوشي.", "كان الإمام والمرشد والمفتي والقاضي والمدرس في قومه.", "اشتهر بالكرم، وبذل العلم والمال مجانا، ونصرة المظلوم.", "مؤلفاته نحو ستين: الرجز المفيد في غريب القرآن (أكثر من 5000 بيت)، النصيحة على شرح خليل."],
  ("ماذا نستفيد من قول شيخه: «ما استفاد مني شيئا إلا استفدت منه مثله»؟", "تواضع الشيخ واعترافه بفضل التلميذ، ونبوغ محمد الأمين وتفوقه."),
  [S("التعريف به", ["محمد الأمين بن أحمد زيدان بن محمد بن المختار الجكني، من قبيلة تجكانت المشهورة بالعلم والكرم.", "ولد حوالي سنة 1229 هـ في الرقيبة أو آفطوط أو تكانت.", "توفي والده مبكرا، فربته أمه فاطمة تربية حسنة."]),
   S("طلبه للعلم وشيوخه", ["تعلم القراءة والكتابة على أمه، وحفظ القرآن على خاله المختار: يقرأ أمامه الثمن والثمنين فيحفظهما من سماع واحد.", "من شيوخه: خاله المختار، الديه بن المختار، السيد أحمد باب، الشريف محمد راره التنواجيوي.", "أنهى رحلته عند سيدي محمد بن علي العلوشي في أصول الفقه."]),
   S("مكانته ومؤلفاته", ["كان الإمام والمرشد والمفتي والقاضي والمدرس، محل ثقة العلماء والأمراء والعامة.", "حسن الخلق، كريم، يبذل العلم والمال للطلبة مجانا، وينصر المظلوم.", "من مؤلفاته: الرجز المفيد على غريب لغة القرآن، منظومة في آداب التلاوة، نظم الأسماء الحسنى وشرحه، النصيحة على شرح خليل."])],
  apps=[("كيف حفظ محمد الأمين القرآن؟", "على خاله المختار، يقرأ أمامه الثمن والثمنين فيحفظهما من حكاية واحدة."), ("لماذا ضاع كثير من مؤلفاته؟", "بسبب التنقل والترحال الغالب على أهل البوادي.")]),
L("الحاج عمر تال الفوتي", [67, 68],
  ["يعرف بالحاج عمر تال الفوتي", "يبين أسباب حركته الإصلاحية ومراحلها", "يوضح جهاده ضد الممالك الوثنية والاستعمار الفرنسي"],
  "قاد الحاج عمر تال الفوتي في القرن التاسع عشر حركة إصلاحية وجهادية واسعة في حوضي نهري السنغال والنيجر. فما أسبابها؟ وإلام انتهت؟",
  "ولد الحاج عمر تال سنة 1797م في حلوار قرب الحدود الموريتانية السنغالية، وطلب العلم في فوتا تورو وأخذ الطريقة التجانية، ثم حج ومر بماسنا والأزهر. دفعه إلى الإصلاح انتشار العادات الوثنية والجهل، وتأثره بحركة عثمان بن فودي. أسس زاويته في فوتا جالون سنة 1841م، ثم هاجر إلى دنغيراي سنة 1848م، وغزا الممالك الوثنية، وواجه الفرنسيين بقيادة فيدرب سنة 1857م، وتوفي سنة 1864م إثر انفجار مخزن سلاحه في كهوف ديغمبيري.",
  ["ولد سنة 1797م في قرية حلوار.", "أخذ الطريقة التجانية في فوتا تورو، وحج، ومر بماسنا والأزهر.", "سببا حركته: انتشار الوثنية والجهل، وتأثره بحركة عثمان بن فودي.", "أسس زاويته سنة 1841م، وهاجر إلى دنغيراي سنة 1848م.", "غزا المالنكي (1850م) والماندينغ (1853م) والبمبارا (1854م).", "واجه الفرنسيين سنة 1857م، وتوفي سنة 1864م."],
  ("ما السببان اللذان دفعا الحاج عمر إلى حركته الإصلاحية؟", "انتشار العادات الوثنية والجهل بعلوم الشرع في فوتا تورو، وتأثره بالحركات الإصلاحية وخاصة حركة عثمان بن فودي في نيجيريا."),
  [S("مولده ورحلته", ["ولد سنة 1797م في قرية «الوار» (حلوار) قرب بودور على الحدود الموريتانية السنغالية، في بيت علم وسيادة.", "درس في فوتا تورو وأخذ الطريقة التجانية.", "في طريقه إلى الحج أقام بماسنا يعلم أبناء الأسرة الحاكمة، ولقي محمد الغالي خليفة التجاني في الحجاز، وزار الأزهر في عودته."]),
   S("مراحل حركته", table=[["السنة", "الحدث"], ["1841م", "تأسيس زاويته في أعالي فوتا جالون"], ["1848م", "الهجرة إلى دنغيراي وإنشاء نواة الجيش والديوان"], ["1850–1854م", "غزو المالنكي والماندينغ وبامبوك والبمبارا (عاصمتها نيورو)"], ["1857م", "حرب الفرنسيين في خاسو بقيادة فيدرب"], ["1861–1862م", "فتح سيغو وحمد الله"], ["1864م", "وفاته إثر انفجار مخزن السلاح في كهوف ديغمبيري"]]),
   S("أثره", ["من أبرز العلماء المجاهدين والأشياخ التجانيين في حوضي السنغال والنيجر.", "أثنى عليه الشيخ محمد المامي في قصيدة."])],
  apps=[("من القائد الفرنسي الذي واجهه الحاج عمر؟", "فيدرب (Faidherbe) سنة 1857م."), ("كيف توفي الحاج عمر تال؟", "إثر انفجار مخزن السلاح في كهوف ديغمبيري سنة 1864م.")]),
L("سيدي عبد الله بن الحاج إبراهيم (المدرسة الأصولية)", [69, 70],
  ["يعرف بسيدي عبد الله بن الحاج إبراهيم", "يتتبع رحلته في طلب العلم", "يبين أثره في المدرسة الأصولية الشنقيطية"],
  "يعد كتاب «مراقي السعود» أشهر متون أصول الفقه في بلاد شنقيط. فمن مؤلفه؟ وكيف أسس النزعة الأصولية في البلاد؟",
  "سيدي عبد الله بن الحاج إبراهيم العلوي، ولد بتجكجة سنة 1152 هـ، وتوفي أبوه في صعيد مصر عائدا من الحج. درس في بلده، ثم على المختار بن بونه وسيدي عبد الله بن الفاضل اليعقوبي، ثم رحل إلى المغرب سبع سنين أو عشرا وأخذ عن البناني والتاودي بن سودة، وحج، وأكرمه سلطان المغرب، وعاد سنة 1190 هـ بمكتبة من نحو أربعمائة كتاب. أسس محظرة موسوعية ذات نزعة أصولية، وأكمل مراقي السعود سنة 1206 هـ وشرحه نشر البنود سنة 1214 هـ.",
  ["ولد بتجكجة سنة 1152 هـ.", "شيوخه في البلد: خاله أحمد بن عبد الله الغلاوي، المختار بن بونه، عبد الله بن الفاضل.", "رحل إلى المغرب: البناني، التاودي بن سودة، وحج ولقي السمان بالمدينة.", "عاد سنة 1190 هـ بنحو أربعمائة كتاب.", "رائد النزعة الأصولية: مراقي السعود (1206 هـ) ونشر البنود (1214 هـ).", "مؤلفات أخرى: هدي الأبرار، فيض الفتاح، رشد الغافل، غرة الصباح."],
  ("لماذا كانت رحلة سيدي عبد الله منعطفا في حياته؟", "لأنه أخذ فيها عن كبار علماء المغرب وحج، ونال التقدير والتكريم، وعاد بمكتبة نفيسة من نحو أربعمائة كتاب."),
  [S("التعريف به", ["عبد الله بن الحاج إبراهيم بن الإمام عبد الرحمن العلوي، أمه مريم غلة بنت عبد الله الغلاوية.", "ولد سنة 1152 هـ بتجكجة، وتوفي أبوه في الصعيد المصري عائدا من الحج سنة 1157 هـ."]),
   S("رحلته في طلب العلم", table=[["المرحلة", "الشيوخ والمواد"], ["تجكجة", "خاله أحمد بن عبد الله الغلاوي، الطالب عبد الرحمن انباب، وغيرهما"], ["محظرة ابن بونه (1172 هـ)", "كافية ابن مالك وتسهيله، ألفية السيوطي في البيان، التلخيص، عقائد السنوسي"], ["محظرة عبد الله بن الفاضل", "الدواوين العربية ولامية الأفعال"], ["المغرب والحج", "البناني، التاودي بن سودة، السمان بالمدينة؛ وأكرمه السلطان سيدي محمد بن عبد الله"]]),
   S("آثاره العلمية", ["محظرة موسوعية لا ترد طالبا، أهم ما ميزها النزعة الأصولية.", "مراقي السعود (أكمله 1206 هـ) وشرحه نشر البنود (1214 هـ، في سبع سنين).", "هدي الأبرار في المصطلح، فيض الفتاح في البلاغة، رشد الغافل، غرة الصباح وشرحها نيل النجاح، مكفرات الذنوب، نظم القراءات الثلاث."])],
  apps=[("ما اسم شرح مراقي السعود؟", "نشر البنود، في جزأين."), ("ماذا عاد به سيدي عبد الله من رحلته؟", "مكتبة كبيرة من نفائس الكتب تبلغ نحو أربعمائة كتاب.")]),
L("الشيخ محمد المامي (1206–1282 هـ)", [71, 73],
  ["يعرف بالشيخ محمد المامي", "يبين موسوعيته ومذهبه في الفقه والعقيدة", "يوضح رأيه في الاجتهاد ويذكر مؤلفاته"],
  "قال بوميه بن أبياه متحيرا في تقديم الشيخ محمد المامي: «هل يقدمه أديبا ولغويا؟ أو فقيها مفتيا؟ أو أصوليا مجتهدا؟…». فمن هذا العالم الموسوعي؟",
  "محمد المامي بن البخاري اليعقوبي الباركي (1206–1282 هـ)، رحل إلى الجنوب واتصل بأئمة الدولة الإمامية وعلماء المنطقة، واشتهر بكثرة التلاميذ. عرف بموسوعية عز نظيرها في الأدب واللغة والفقه والأصول والمنطق والسياسة. كان مالكيا أشعريا، يرى فتح باب الاجتهاد في النوازل التي لا نص فيها ولا اجتهاد سابق، ووجوب اتباع الأئمة فيما اجتهدوا فيه. ومن مؤلفاته: نظم مختصر خليل (نحو 10000 بيت)، وكتاب البادية، وسفينة النجاة.",
  ["محمد المامي بن البخاري اليعقوبي الباركي (1206–1282 هـ).", "اتصل بأئمة الدولة الإمامية وعلماء عصره كابن متالي والكنتي الصغير.", "اشتهر بكثرة التلاميذ، ومنهم أبناؤه العشرة.", "مالكي في الفروع، أشعري في العقيدة.", "يرى الاجتهاد في النوازل الجديدة، واتباع الأئمة فيما اجتهدوا فيه.", "مؤلفاته: نظم مختصر خليل، كتاب البادية، سفينة النجاة، الدلفينية، الميزابية."],
  ("ما رأي الشيخ محمد المامي في الاجتهاد؟", "يرى فتح بابه في النوازل الطارئة إذا عدم النص واجتهاد السابقين، ويرى وجوب اتباع الأئمة فيما اجتهدوا فيه وعدم تأسيس مذهب جديد."),
  [S("التعريف به", ["محمد المامي بن البخاري بن حبيب الله اليعقوبي الباركي، أمه مريم بنت محمود.", "اتصل بأئمة الدولة الإمامية وبعلماء منهم: اليعقوب بن أبي حامد، أحمد البشير الغلاوي، الشيخ سيدي المختار الكنتي الصغير، محمذن فال بن متالي، محنض باب بن اعبيد.", "اشتهر بكثرة التلاميذ، وخصصت لهم خيمة (الزاوية) يقسمونها نصفين عند الرحيل."]),
   S("مذهبه ونظره في الاجتهاد", ["مالكي في الفروع، يعتقد معتقد أهل السنة على طريقة أبي الحسن الأشعري.", "يرى الاجتهاد في النوازل إذا عدم النص وعدم اجتهاد السابقين، خوفا من ضياع الحق.", "«ففي تقليد صاحبه اكتفاء — ليقنعنا بمذهبنا اقتفاء».", "يرى الجدل الكلامي في زمانه اختلافا في الأفهام والمصطلحات لا عيب فيه."]),
   S("مؤلفاته", ["المطبوع: نظم مختصر خليل (نحو 10000 بيت)، سفينة النجاة، رد الضوال، كتاب البادية، كتاب الجمان، الدلفينية والميزابية وشرحاهما.", "المخطوط: ديوانه، نظم القواعد المالكية وشرحه، كتاب الإجماعات، نظم ورقات إمام الحرمين، لاميته في علوم القرآن.", "مدح النبي ﷺ بقصيدة من 488 بيتا."])],
  apps=[("ما أشهر عمل فقهي للشيخ محمد المامي؟", "نظم مختصر خليل في نحو عشرة آلاف بيت."), ("ما مذهبه في العقيدة؟", "أشعري على معتقد أهل السنة.")]),
L("المختار بن بونه: نزعته الكلامية والأصولية", [74, 75],
  ["يعرف بالمختار بن بونه ونشأته", "يبين أثره في تلاميذه والنهضة العلمية", "يوضح نزعته الكلامية والأصولية"],
  "يكاد يكون جميع أركان النهضة العلمية في بلاد شنقيط بعده من تلاميذه، ومنهم صاحب «مراقي السعود». فمن هو المختار بن بونه؟",
  "المختار بن محمد سعيد (بونه) الجكني، من أبرز النحاة في بلاد شنقيط، توفي سنة 1220 هـ/1805م. نشأ في بيت علم، وأخذ عن علماء البلد دون رحلة خارجها، ودرس كل الفنون المحظرية، وعني بالعربية عناية خاصة، ونظم في كل فن. من تلاميذه: النابغة الغلاوي، وسيدي عبد الله بن الحاج إبراهيم، ومحنض باب بن اعبيد، والمجيدري. وأهم مؤلفاته: احمرار ألفية ابن مالك وطرتها، ووسيلة السعادة في الكلام، ومبلغ المأمول (نظم جمع الجوامع). وعلى يديه بلغت المدرسة الكلامية أشدها.",
  ["المختار بن محمد سعيد (بونه) الجكني، توفي سنة 1220 هـ/1805م.", "أخذ عن علماء البلد كالمختار بن باباه وخديجة بنت العاقل، ولم يرحل خارج القطر.", "عني بالعربية نحوا وصرفا وبلاغة وأدبا، ونظم في كل فن.", "تلاميذه: النابغة الغلاوي، سيدي عبد الله، محنض باب، المجيدري.", "مؤلفاته: احمرار الألفية وطرتها، الوسيلة، مبلغ المأمول.", "بلغت المدرسة الكلامية في شنقيط أشدها على يديه."],
  ("لماذا نظم ابن بونه في كل فن؟", "سعيا إلى تسهيل العلوم وتقريبها لتلاميذه."),
  [S("التعريف به ونشأته", ["المختار بن محمد سعيد (بونه) الجكني، من أبرز النحاة في بلاد شنقيط، توفي سنة 1220 هـ/1805م.", "«ولما ظهر ابن بونه وانتشر ذكره أقبل الناس يفدون إليه من كل جهة» (الوسيط).", "أخذ عن المختار بن باباه، وألفغ المختار الحسنيني، والمختار بن حبيب الجكني، وخديجة بنت العاقل."]),
   S("تلاميذه ومؤلفاته", table=[["التلميذ", "أشهر آثاره"], ["النابغة الغلاوي", "منظومة «بوطليحة» في كتب المذهب المالكي"], ["سيدي عبد الله بن الحاج إبراهيم", "مراقي السعود"], ["محنض باب بن اعبيد", "سلم الوصول إلى علم الأصول"], ["المجيدري بن حبل", "الصراط المستقيم"]]),
   S("نزعته الكلامية والأصولية", ["كان درس العقيدة في شنقيط قبل النصف الثاني من القرن 11 هـ مقتصرا على مقدمة رسالة ابن أبي زيد القيرواني.", "بلغت المدرسة الكلامية أشدها على يد ابن بونه، وتخرج عليه حرمة بن عبد الجليل ومولود بن أحمد الجواد.", "أشهر مؤلفاته في الكلام «الوسيلة»، وفي الأصول «مبلغ المأمول» نظم فيه جمع الجوامع للسبكي وشرحه.", "وفي النحو: احمرار ألفية ابن مالك وطرتها (الجامع بين التسهيل والخلاصة)."]),
   S("(تصحيح: …)", ["ص75: «رسالة ابن أبي زيد القيرواني المتوفى في 550هـ». (تصحيح: توفي ابن أبي زيد القيرواني سنة 386 هـ.)"])],
  apps=[("ما «احمرار الألفية»؟", "زيادات ابن بونه على ألفية ابن مالك من التسهيل، وسماه الجامع بين التسهيل والخلاصة."), ("من صاحب «بوطليحة»؟", "النابغة الغلاوي، تلميذ ابن بونه.")]),
L("لمجيدري ولد حبل ومنهجه السلفي (1156–1204 هـ)", [76, 76],
  ["يعرف بلمجيدري ولد حبل", "يتتبع رحلته العلمية", "يبين منهجه السلفي وموقف علماء عصره منه"],
  "أثار لمجيدري بعد عودته من الحج «زوبعة» في بلاد شنقيط بإنكاره الخوض في علم الكلام. فما منهجه؟ وكيف استقبله علماء عصره؟",
  "محمذن (كمال الدين) بن حبيب الله اليعقوبي الموسوي، المعروف بلمجيدري ولد حبل (1156–1204 هـ)، لقبه سلطان المغرب بذلك لأثر الجدري في وجهه. كان فقيها متبحرا ولغويا ومناظرا بارعا، وعد رابع أربعة لم يبلغ أحد مبلغهم. درس على المختار بن ألفغ موسى وابن بونه، ورحل إلى المغرب ومصر (حيث صحح مع الزبيدي تاج العروس) والحجاز. دعا إلى الرجوع إلى الكتاب والسنة في الفقه والعقيدة ومنع الخوض في علم الكلام، فنسبه علماء عصره إلى البدعة وتصدى له ابن بونه.",
  ["محمذن بن حبيب الله اليعقوبي (1156–1204 هـ)، لقب لمجيدري لأثر الجدري.", "رابع أربعة: اليدالي، سيدي عبد الله، ابن رازكه، لمجيدري.", "تربى على المختار بن ألفغ موسى، ودرس على ابن بونه.", "رحل إلى المغرب ومصر والحجاز، وصحح تاج العروس مع الزبيدي.", "منهجه: الرجوع إلى الكتاب والسنة، ومنع الخوض في علم الكلام، وإثبات الصفات على منهج السلف.", "مؤلفاته: الأسئلة المتحدية لمن ينتصر لعلم الكلام، السراج الوهاج، مبين الصراط المستقيم."],
  ("لماذا عارض علماء شنقيط دعوة لمجيدري؟", "لأن أهل البلاد استقروا على مشهور مذهب مالك في مختصر خليل وعقيدة الأشعري، ورأوا في إنكاره علم الكلام والاعتماد على الفروع خروجا عن ذلك."),
  [S("التعريف به", ["محمذن (كمال الدين) بن حبيب الله بن الفاضل اليعقوبي الموسوي، أمه مريم بنت ألفغ محمد المجلسية.", "لقبه سلطان المغرب «لمجيدري» لنكت من أثر الجدري في وجهه.", "بهر علماء المغرب ومصر والحجاز بحافظته وسرعة بديهته."]),
   S("رحلته", table=[["المحطة", "ما كان فيها"], ["المغرب", "قربه السلطان محمد بن عبد الله، وصحبه أحمد بن إدريس الفاسي"], ["مصر", "لقي مرتضى الزبيدي وعكف معه على تصحيح تاج العروس"], ["الحجاز", "حج وأخذ عن علمائه وأخذوا عنه"]]),
   S("منهجه السلفي", ["الرجوع إلى الكتاب والسنة في الفقه والعقيدة، وإنكار الاتكاء على الفروع دون دليل.", "منع الخوض في علم الكلام، وإثبات الصفات على منهج السلف.", "يجيز التوسل بالنبي ﷺ، ولا يرى تعلق قدرة الله بالمستحيلات.", "أطلق خصومه على دعوته «بدعة لمجيدري»، وتصدى له ابن بونه وتلاميذه."]),
   S("مؤلفاته", ["الأسئلة المتحدية لمن ينتصر لعلم الكلام.", "السراج الوهاج في بيان المنهاج.", "مبين الصراط المستقيم، الجواهر المكنونة، الجوهر المنظوم، تذييل مثلث قطرب."])],
  apps=[("من الأربعة الذين اشتهروا بأنه لم يبلغ أحد مبلغهم؟", "محمد اليدالي، وسيدي عبد الله بن الحاج إبراهيم، وابن رازكه، ولمجيدري."), ("ما الكتاب الذي رد فيه على أنصار علم الكلام؟", "الأسئلة المتحدية لمن ينتصر لعلم الكلام.")]),
L("الشيخ سيدي المختار الكنتي: حياته ومنهجه في التصوف", [77, 78],
  ["يعرف بالشيخ سيدي المختار الكنتي", "يبين طلبه للعلم ومنهجه في الجمع بين الأصول والفروع", "يذكر بعض مؤلفاته وتلاميذه"],
  "كان الشيخ سيدي المختار الكنتي زعيما للطريقة القادرية في غرب إفريقيا، وتخرج عليه خلائق لا يحصون. فما منهجه؟",
  "الشيخ سيدي المختار بن أحمد بن أبي بكر الكنتي، ولد سنة 1142 هـ/1730م في أزواد، من قبيلة كنتة التي ترجع إلى عقبة بن نافع. طلب العلم في الثامنة عشرة حتى وجد شيخه سيدي علي بن النجيب، فأخذ عنه العلوم والطريقة القادرية. ألف كتبا كثيرة، وكان يمزج بين الأصول والفروع، يتمسك بالكتاب والسنة ويرى أن كتب الفروع كمختصر خليل مستنبطة منهما. توفي سنة 1226 هـ عن 84 سنة ودفن في بو الأنوار.",
  ["ولد سنة 1142 هـ/1730م في كثيب أوغال بأزواد.", "من قبيلة كنتة التي ترجع إلى عقبة بن نافع الفهري.", "شيخه: سيدي علي بن النجيب، أخذ عنه العلوم والطريقة القادرية.", "منهجه: التمسك بالكتاب والسنة مع اعتبار الفروع المستنبطة منهما.", "مؤلفاته: تفسير البسملة، هداية الطالب، فتح الوهاب، جذوة الأنوار، الرسالة في التصوف.", "توفي سنة 1226 هـ ودفن في بو الأنوار."],
  ("كيف جمع الكنتي بين التمسك بالأصلين والعمل بمختصر خليل؟", "رأى أن ما في كتب الفروع مستنبط من الكتاب والسنة: «فما هو إلا جامع المنهل الذي — نماه إلى الأصلين كل نبيل»."),
  [S("حياته", ["سيدي المختار بن أحمد بن أبي بكر الكنتي، ولد سنة 1142 هـ/1730م في كثيب أوغال بأزواد (شمال مالي اليوم).", "نشأ في أسرة علم وصلاح، وطلب العلم في الثامنة عشرة متنقلا حتى لقي سيدي علي بن النجيب.", "عاد عالما بالشريعة، عارفا بالحقيقة، زعيما للطريقة القادرية.", "توفي يوم الأربعاء 5 جمادى الأولى 1226 هـ عن 84 سنة، ودفن في بو الأنوار."]),
   S("منهجه", ["يمزج بين الأصول والفروع:", "«تمسكت بالأصلين آي وسنة — ولم أك أصغي فيهما لعذول — على أنني والحمد لله لم أكن — لأترك بين الناس نص خليل»."]),
   S("مؤلفاته وتلاميذه", ["من مؤلفاته: تفسير البسملة، بلوغ الوسع على الآيات التسع، هداية الطالب، فتح الوهاب، فتح الودود على المقصور والممدود، نصيحة المنصف، ألفية في العربية، جذوة الأنوار، الرسالة في التصوف.", "من تلاميذه وتلاميذ ابنه سيدي محمد: الشيخ سيديا الكبير، الشيخ محمد فال بن باب، الشيخ المصطفى بن العربي."])],
  apps=[("إلى من ينتسب الكنتيون؟", "إلى عقبة بن نافع الفهري فاتح إفريقيا."), ("ما الطريقة التي تزعمها الكنتي؟", "الطريقة القادرية.")]),
L("محمد الأمين بن محمد المختار الشنقيطي (آبه بن أخطور): حياته ومنهجه في التفسير", [79, 80],
  ["يعرف بالشيخ محمد الأمين الشنقيطي", "يبين مكانته العلمية وثناء العلماء عليه", "يوضح منهجه في التفسير في «أضواء البيان»"],
  "قال عنه الشيخ محمد بن إبراهيم: «آبه ملئ علما من رأسه إلى أخمص قدميه». فمن هو صاحب «أضواء البيان»؟",
  "محمد الأمين بن محمد المختار الجكني الشنقيطي (آبه بن أخطور)، ولد سنة 1325 هـ، ونشأ يتيما في كفالة أخواله، وتولى القضاء في بلده، ثم استقر بالسعودية بعد الحج، فدرس في الجامعة الإسلامية، وكان عضوا في رابطة العالم الإسلامي وهيئة كبار العلماء. أثنى عليه ابن باز والألباني وغيرهما. ومنهجه في التفسير: تفسير القرآن بالقرآن، ثم بالسنة، ثم بأقوال الصحابة، مع استخلاص المباحث الأصولية والفقهية والبلاغية. توفي بمكة في 17 ذي الحجة 1393 هـ.",
  ["ولد سنة 1325 هـ، ونشأ يتيما في كفالة أخواله.", "تولى القضاء في بلده، ثم استقر بالسعودية.", "درس بالجامعة الإسلامية (1381 هـ)، وعضو هيئة كبار العلماء (1391 هـ).", "مؤلفاته: أضواء البيان، دفع إيهام الاضطراب، مذكرة أصول الفقه، آداب البحث والمناظرة.", "منهجه: تفسير القرآن بالقرآن ثم بالسنة ثم بأقوال الصحابة.", "توفي بمكة في 17 ذي الحجة 1393 هـ ودفن بالمعلاة."],
  ("ما أحسن طرق التفسير عند الشنقيطي؟", "تفسير القرآن بالقرآن، ثم بالسنة، ثم بأقوال الصحابة، وعلى ذلك بنى «أضواء البيان»."),
  [S("حياته", ["محمد الأمين بن محمد المختار (آبه ولد اخطور) الجكني الشنقيطي، ولد سنة 1325 هـ.", "نشأ يتيما، فدرس علوم القرآن والسيرة والأدب والتاريخ، ونال الإجازات.", "تولى القضاء في بلده، ثم استقر بالسعودية بعد رحلته إلى الحج.", "من أوائل مدرسي الجامعة الإسلامية (1381 هـ)، وعضو مجلس تأسيس رابطة العالم الإسلامي، وعضو هيئة كبار العلماء (1391 هـ).", "توفي بمكة في 17 ذي الحجة 1393 هـ، ودفن بالمعلاة."]),
   S("ثناء العلماء عليه", ["محمد بن إبراهيم: «آبه ملئ علما من رأسه إلى أخمص قدميه».", "ابن باز: «من سمع كلامه حين يتكلم في التفسير يعجب كثيرا من سعة علمه».", "الألباني: ما رأيت مثله في جمعه للعلوم، وشبهه بابن تيمية."]),
   S("مؤلفاته ومنهجه", ["أضواء البيان في إيضاح القرآن بالقرآن ؛ دفع إيهام الاضطراب عن آيات الكتاب ؛ الأسماء والصفات نقلا وعقلا ؛ مذكرة أصول الفقه على روضة الناظر ؛ آداب البحث والمناظرة ؛ ألفية في المنطق ؛ خالص الجمان في أنساب العرب ؛ رحلة الحج.", "منهجه: يفسر مشكل القرآن بمبينه، فإن لم يجد فبالسنة، ثم بأقوال الصحابة، ثم يستخلص المباحث الأصولية والفقهية والبلاغية والقراءات."]),
   S("(تصحيح: …)", ["ص79: «ولد سنة 1325هـ الموافق 1905». (تصحيح: سنة 1325 هـ توافق 1907م.)"])],
  apps=[("ما اسم تفسير الشنقيطي؟", "أضواء البيان في إيضاح القرآن بالقرآن."), ("أين توفي الشنقيطي؟", "بمكة بعد أداء الحج سنة 1393 هـ، ودفن بمقبرة المعلاة.")]),
